package oepul.o6_21

import rego.v1

g := input.farm.oepul

size_met if g.participation_year_number >= 2

size_met if {
	g.participation_year_number == 1
	g.protected_cultivation_at_ha >= 0.5
}

size_met if {
	g.participation_year_number == 1
	g.qualifying_at_ha >= 1.5
}

applicant_ok if {
	g.legal_form in {"natural", "registered_partnership", "legal_person", "association"}
	g.active_farmer
	g.agricultural_activity
	g.own_name_and_account
	g.land_at_disposal
	g.public_entity_or_controlled_subsidiary == false
	g.public_share_pct >= 0
	g.public_share_pct <= 25
	g.equivalent_public_influence == false
}

forage_crop(name) if name in cfg.forage_crops

annex_units(group, category_name, heads) := row.factor * heads if {
	some row in cfg.key_annex_a
	row.group == group
	row.category == category_name
	heads >= 0
}

livestock_density_met if {
	forage := input.land.grassland_area_ha + g.arable_forage_ha
	forage > 0
	g.all_annual_rgve >= 0.3 * forage
}

takeover_reviewable if {
	claim.takeover.event in cfg.takeover_events
	claim.takeover.same_previous_farm
	claim.takeover.online_mfa_submitted
}

max_occupancy(area, weight) := floor(area / max([r.total_m2 | some r in rows])) if {
	area >= 0
	rows := space_rows({"cow": false, "weight_kg": weight})
	count(rows) == 1
}

sanction_percent(y, code) := r.until_2026_percent if {
	some r in cfg.sanctions
	r.code == code
	y >= 2023
	y <= 2026
} else := r.percent if {
	some r in cfg.sanctions
	r.code == code
	y >= 2027
}

repeated_full_cut if g.full_cuts_in_contract >= 2
cut_sequence := cfg.cut_order
payment_deadline := sprintf("%d-06-30", [year + 1])

maximum_advance := g.expected_premium_eur * 0.75 if {
	g.administrative_checks_complete
	g.expected_premium_eur >= 0
}

# Positive findings require the inputs for the particular check.
stable_checks[id] := {"structure_met": stable_structure(s)} if {
	some s in claim.stables
	id := s.id
}

bedded_pens contains p.id if {
	some p in claim.pens
	bedding_ok(p)
}

permitted_events contains idx if {
	some idx, e in claim.housing_events
	housing_mode_ok(e)
}

package oepul.o6_21

import rego.v1

cfg := data.o6_21_tables
claim := input.o6_21
year := input.farm.year
day_ns := 86400000000000

day(date) := time.parse_rfc3339_ns(sprintf("%sT00:00:00Z", [date])) / day_ns
jan(y) := day(sprintf("%04d-01-01", [y]))
days_in_year := jan(year + 1) - jan(year)

# Register intervals run from the first through the last attributed day.
# Age bands use calendar anniversaries of the registered date of birth.
category(sex, months) := row.code if {
	months >= 0
	some row in cfg.categories
	row.sex == sex
	months >= row.from_month
	below_limit(months, row.until_month)
}

below_limit(n, limit) if {
	is_number(n)
	limit == null
}

below_limit(n, limit) if {
	is_number(limit)
	n < limit
}

breed_class(breed) := "dwarf" if lower(breed) in cfg.dwarf_breeds

else := "standard" if {
	is_string(breed)
	breed != ""
}

rgve_per_head(breed, months) := row.factor if {
	some row in cfg.cattle_rgve
	row.class == breed_class(breed)
	months >= row.from_month
	below_limit(months, row.until_month)
}

milk_allows(code) if code != "female_6_24"
milk_allows("female_6_24") if claim.dairy_delivery == false

register_valid if {
	is_number(year)
	year == floor(year)
	year >= 2023
	year <= 2028
	is_array(claim.cattle)
	is_array(claim.categories)
	is_boolean(claim.dairy_delivery)
	every c in claim.categories {
		some r in cfg.categories
		c == r.code
	}
	tags := {a.tag | some a in claim.cattle}
	count(tags) == count(claim.cattle)
	every a in claim.cattle {
		is_string(a.tag)
		a.tag != ""
		a.sex in {"male", "female"}
		is_string(a.breed)
		a.breed != ""
		is_number(day(a.birth_date))
		is_boolean(a.withdrawn_for_year)
		is_boolean(a.animal_conditions_met)
		is_array(a.overlap_claims)
		every benefit in a.overlap_claims { benefit in cfg.overlap_claims }
		is_array(a.periods)
		every p in a.periods {
			day(p.first_day) <= day(p.last_day)
			is_string(p.country)
			p.country != ""
			day(p.first_day) >= day(a.birth_date)
		}
		not overlapping(a.periods)
	}
}

overlapping(periods) if {
	some i, j
	a := periods[i]
	b := periods[j]
	i < j
	a.first_day <= b.last_day
	b.first_day <= a.last_day
}

# Clamp an anniversary to month end when the birth day does not exist there.
anniversary(birth, months) := result if {
	[y, m, d] := time.date(day(birth) * day_ns)
	first := day(sprintf("%04d-%02d-01", [y, m])) * day_ns
	target := time.add_date(first, 0, months, 0) / day_ns
	following := time.add_date(first, 0, months + 1, 0) / day_ns
	result := min([(target + d) - 1, following - 1])
}

band_end(_, null) := jan(year + 1)
band_end(birth, months) := anniversary(birth, months) if is_number(months)

animal_rgve_days(a, code) := sum([amount |
	some p in a.periods
	p.country == "AT"
	some band in cfg.cattle_rgve
	band.class == breed_class(a.breed)
	category(a.sex, band.from_month) == code
	first := max([jan(year), day(p.first_day), anniversary(a.birth_date, band.from_month)])
	end := min([jan(year + 1), day(p.last_day) + 1, band_end(a.birth_date, band.until_month)])
	end > first
	amount := (end - first) * band.factor
])

eligible_tag(a) if {
	a.withdrawn_for_year == false
	a.animal_conditions_met == true
	not a.tag in animal_withdrawal_due
}

# Numerator is retained until totals are added (including in leap years).
credited_days(a, code) := animal_rgve_days(a, code) if {
	eligible_tag(a)
	milk_allows(code)
	code in claim.categories
} else := 0

annual_rgve := sum([total |
	some a in claim.cattle
	some r in cfg.categories
	total := credited_days(a, r.code)
]) / days_in_year if {
	register_valid
}

minimum_participation_met := annual_rgve >= 2

expired_categories contains code if {
	register_valid
	some code in claim.categories
	not represented(code)
}

represented(code) if {
	some a in claim.cattle
	credited_days(a, code) > 0
}

rates := r if {
	some r in cfg.premiums
	year >= r.from_year
	year <= r.through_year
}

base_rate(a) := rates.reduced if {
	some benefit in a.overlap_claims
	benefit in cfg.overlap_claims
} else := rates.basic

# Tariff calculation before administrative assessment and sanctions.
base_amount_eur := sum([amount |
	some a in claim.cattle
	some r in cfg.categories
	amount := credited_days(a, r.code) * base_rate(a)
]) / days_in_year if {
	register_valid
	minimum_participation_met
	rates.basic > 0
}

compost_amount_eur := annual_rgve * rates.compost if {
	minimum_participation_met
	claim.compost.requested
	compost_ok
} else := 0 if {
	minimum_participation_met
	claim.compost.requested == false
}

modulation_factor(ha) := 1 if ha == 0

else := weighted / ha if {
	is_number(ha)
	ha > 0
	weighted := sum([value |
		some r in cfg.modulation
		upper := min([ha, object.get(r, "through_ha", ha)])
		value := max([0, upper - r.from_ha]) * r.factor
	])
}

modulated_tariff_eur := (base_amount_eur + compost_amount_eur) * modulation_factor(input.farm.oepul.home_area_ha)

program_start(y) := sprintf("%d-04-15", [y]) if y == 2023

else := sprintf("%d-01-01", [y])

program_covers_year(program) if {
	program.recognised
	day(program.start) <= day(program_start(year))
	day(program.end) >= jan(year + 1) - 1
}

tgd_required := claim.eligible_cattle_rgve > 10 if {
	is_number(claim.eligible_cattle_rgve)
	claim.eligible_cattle_rgve >= 0
}

qplus_required := count({c | some c in claim.categories; some r in cfg.categories; r.code == c; r.sex == "female"}) > 0 if is_array(claim.categories)

tgd_met if tgd_required == false
tgd_met if program_covers_year(claim.tgd)
qplus_met if qplus_required == false
qplus_met if program_covers_year(claim.qplus)

proof_due(program) if {
	program.ama_requested
	program.transmitted_by_provider == false
}

proof_outstanding contains name if {
	some name in {"qplus", "tgd"}
	program_required(name)
	proof_due(claim[name])
	claim[name].submitted == false
}

default entry_timely(_, _, _) := false

entry_timely(kind, date, y) if {
	limit := {"category": 2027, "compost": 2028}[kind]
	y >= 2023
	y <= limit
	day(date) < jan(y)
}

entry_checks := [entry |
	some a in claim.applications
	entry := {"kind": a.kind, "date": a.date, "year": a.target_year, "timely": entry_timely(a.kind, a.date, a.target_year)}
] if {
	is_array(claim.applications)
}

program_required("tgd") if tgd_required
program_required("qplus") if qplus_required

# Explicit renewal/termination events, separate from the tariff calculation.
contract_effects contains "Maßnahmenvertrag wegen Mindestteilnahme erloschen" if minimum_participation_met == false

contract_effects contains "Abmeldung im laufenden Förderjahr wirksam" if {
	day(claim.withdrawal_date) >= jan(year)
	day(claim.withdrawal_date) < jan(year + 1)
}

contract_effects contains "Neuer Maßnahmenantrag erforderlich" if {
	claim.previous_status in {"withdrawn", "excluded", "mfa_missing_one_year"}
}

contract_effects contains "Online-Korrektur und schriftliches Ersuchen erforderlich" if {
	claim.previous_status == "category_empty"
	claim.immediate_reentry
	day(claim.reentry_application_date) >= jan(year)
}

contract_effects contains "Jährliche Weiterführung beantragt" if {
	claim.previous_status == "active"
	claim.withdrawal_date == null
	claim.current_mfa_with_units
	minimum_participation_met
	year <= 2028
}

per_animal_rgve[tag] := contributions if {
	register_valid
	some a in claim.cattle
	tag := a.tag
	contributions := {c: amount | some c in claim.categories; amount := credited_days(a, c) / days_in_year}
}

package oepul.o6_21

import rego.v1

stable_structure(s) if {
	s.type == "ordinary"
	is_number(s.wind_protected_sides)
	s.wind_protected_sides >= 3
	s.lying_area_roofed
	s.solid_floor
	is_string(s.floor_material)
	s.floor_material != ""
	s.floor_material != "gravel"
	s.floor_material != "clay"
	liquid_handled(s)
}

stable_structure(s) if {
	s.type == "open"
	s.fixed_roof_over_beds
	s.impermeable_surface
	s.drain_to_collection_pit
}

liquid_handled(s) if s.liquid_arises == false
liquid_handled(s) if s.collection_container

usable_area(pen) := sum([part.area_m2 |
	some part in pen.surfaces
	part.paved
	part.access in {"permanent", "routine_work_only"}
]) if {
	is_array(pen.surfaces)
	every part in pen.surfaces {
		is_number(part.area_m2)
		part.area_m2 >= 0
		is_boolean(part.paved)
		part.access in {"permanent", "routine_work_only", "restricted"}
	}
}

# At 500 kg both published labels apply. Compare both totals before deciding.
space_rows(group) := cfg.cow_space if group.cow

else := [r |
	some r in cfg.weight_space
	lower_weight(group.weight_kg, r)
	upper_weight(group.weight_kg, r)
] if {
	group.cow == false
	is_number(group.weight_kg)
	group.weight_kg > 0
}

lower_weight(kg, r) if kg > r.from_kg

lower_weight(kg, r) if {
	r.from_inclusive
	kg == r.from_kg
}

upper_weight(kg, r) if {
	is_number(kg)
	r.through_kg == null
}

upper_weight(kg, r) if {
	is_number(r.through_kg)
	kg <= r.through_kg
}

space_need(pen, field, mode) := sum([value |
	some g in pen.occupants
	values := [r[field] | some r in space_rows(g)]
	value := g.count * bound(values, mode)
]) if {
	field in {"total_m2", "lying_m2"}
	mode in {"lower", "upper"}
	is_array(pen.occupants)
	count(pen.occupants) > 0
	every g in pen.occupants {
		is_number(g.count)
		g.count == floor(g.count)
		g.count > 0
		count(space_rows(g)) > 0
	}
}

bound(xs, "lower") := min(xs)
bound(xs, "upper") := max(xs)

cubicle_space_ok(pen) if {
	pen.suckler_cow_cubicle_system
	pen.legal_total_space
	pen.legal_cubicle_each_over_six_months
	pen.calf_beds_always_accessible_free_lying
	is_number(pen.calf_creep_bedded_m2)
	is_number(pen.calf_required_total_m2)
	pen.calf_creep_bedded_m2 >= 0.4 * pen.calf_required_total_m2
	pen.calf_required_total_m2 >= 0
}

ordinary_space_ok(pen, mode) if {
	usable_area(pen) >= space_need(pen, "total_m2", mode)
	is_number(pen.bedded_lying_m2)
	pen.bedded_lying_m2 >= space_need(pen, "lying_m2", mode)
}

space_assessment(pen) := "erfüllt" if cubicle_space_ok(pen)

else := "erfüllt" if {
	ordinary_space_ok(pen, "upper")
} else := "Grenze 500 kg klären" if {
	ordinary_space_ok(pen, "lower")
	not ordinary_space_ok(pen, "upper")
	pen.suckler_cow_cubicle_system == false
} else := "unterschritten" if {
	pen.suckler_cow_cubicle_system == false
	is_number(usable_area(pen))
	is_number(pen.bedded_lying_m2)
	is_number(space_need(pen, "total_m2", "lower"))
	not ordinary_space_ok(pen, "lower")
}

bedding_ok(pen) if {
	pen.perforation_pct >= 0
	pen.perforation_pct <= 5
	pen.bedding_soft_absorbent
	pen.lying_surface_soft_dry
	bedding_depth_ok(pen)
}

bedding_depth_ok(pen) if {
	pen.lying_base == "soft_depressible"
	pen.bedded
}

bedding_depth_ok(pen) if {
	pen.lying_base == "hard"
	is_number(pen.bedding_depth_cm)
	pen.bedding_depth_cm >= 3
	pen.continuous_rebedding
}

housing_mode_ok(e) if {
	e.mode == "group"
	e.bedded
}

housing_mode_ok(e) if {
	e.mode == "individual"
	e.bedded
	e.medical_necessity
	e.ill_or_injured
	e.duration_days >= 1
	e.duration_days <= 10
}

housing_mode_ok(e) if {
	e.mode == "individual"
	e.bedded
	e.age_days_at_end >= 0
	e.age_days_at_end < 21
	e.calf_social_contact
	e.meets_thvo
}

housing_mode_ok(e) if {
	e.mode in {"pasture", "alpine"}
	e.compliant_home_stall
	e.actual_stabling_in_year
}

medical_records_due(e) if {
	e.mode == "individual"
	e.medical_necessity
	e.ill_or_injured
}

animal_withdrawal_due contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	e.conditions_unattainable
}

animal_withdrawal_due contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	medical_records_due(e)
	is_number(e.duration_days)
	e.duration_days > 10
}

pen_space[id] := status if {
	some pen in claim.pens
	id := pen.id
	status := space_assessment(pen)
}

plans_required := year <= 2024 if year >= 2023

compost_ok if {
	c := claim.compost
	c.requested
	c.all_species_manure_on_farm_in_heaps
	c.compost_barn == false
	c.nitrate_rules_met
	c.records_complete
	count(c.heaps) > 0
	every heap in c.heaps { heap_ok(heap) }
}

heap_ok(h) if {
	some i, j
	a := h.turns[i]
	b := h.turns[j]
	day(b.date) - day(a.date) >= 14
	turn_ok(a)
	turn_ok(b)
}

heap_ok(h) if {
	year >= 2025
	h.mixed_or_layered
	h.significant_added_field_or_woody_material
	h.composting_process
}

turn_ok(t) if {
	equipment_ok(t)
	t.on_farm_equipment
}

turn_ok(t) if {
	equipment_ok(t)
	t.external_use_documented
}

equipment_ok(t) if t.device == "turner"

equipment_ok(t) if {
	t.device in {"spreader", "other"}
	t.fully_turned
	t.equivalent_result
}

# An evidenced deficiency in a linked occupied pen applies to the affected tag.
animal_withdrawal_due contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	e.mode in {"group", "individual"}
	some p in claim.pens
	p.id == e.pen_id
	space_assessment(p) == "unterschritten"
}

animal_withdrawal_due contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	e.mode in {"group", "individual"}
	e.bedded == false
}

animal_withdrawal_due contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	e.mode in {"tethered", "fully_slatted"}
}

animal_withdrawal_due contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	e.mode == "individual"
	e.age_days_at_end >= 21
	e.medical_necessity == false
}

medical_records_missing contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	medical_records_due(e)
	e.medical_reason_and_duration_recorded == false
}

# Even sufficient remaining space does not permit locking part of the pen.
restricted_pens contains p.id if {
	some p in claim.pens
	some part in p.surfaces
	part.access == "restricted"
}

animal_withdrawal_due contains e.tag if {
	some e in claim.housing_events
	e.participating_category
	e.mode in {"pasture", "alpine"}
	e.actual_stabling_in_year == false
	e.compliant_home_stall == false
}

plan_missing contains {"pen_id": p.id, "category": c} if {
	plans_required
	some p in claim.pens
	some c in p.participating_categories
	is_array(input.documentation.o6_21_pen_plans)
	not documented_pen(p.id, c)
}

documented_pen(id, c) if {
	some plan in input.documentation.o6_21_pen_plans
	plan.pen_id == id
	plan.category == c
	plan.kept_on_farm
	plan.dimensions_recorded
	plan.area_m2 > 0
	plan.max_head_count >= 1
}

package oepul.o6_21

import rego.v1

# Reference queries for co-claimed land measures. Their results do not enter cattle RGVE.
programme := data.o6_programmkontext

crop_groups(name, y) := {r.group | some r in programme.crop_groups; r.crop == name; y >= r.from_year}

area_ceiling(group, y) := r if {
	some r in programme.area_ceiling
	r.group == group
	y >= r.from_year
	y <= r.through_year
}

contract_term(code) := r.period if {
	some r in programme.contracts
	r.measure == code
}

duration_of(start) := r if {
	some r in programme.multiyear_periods
	r.start == start
}

switch_allowed(src, dst, y) if {
	some r in programme.contract_switch
	r.source == src
	r.target == dst
	y >= 2023
	y <= r.last_source_year
}

combination_cell(src, dst) := {"entry": row.cells[dst], "footnotes": programme.combination_notes} if {
	some row in programme.area_combinations
	row.measure == src
}

allowed_area_loss(prior_ha) := max([0.5, min([5, prior_ha * 0.05])]) if prior_ha >= 0

div_option(code) := r.regular_use if {
	some r in programme.div_options
	r.code == code
}

drought_harvest_waiver(parcel, y) if {
	y == 2026
	parcel.drought_no_harvest
	parcel.normally_late_summer_or_autumn
	some area in programme.drought_districts
	area.state == parcel.state
	area.district in {"alle Bezirke", parcel.district}
}

structural_takeover_activity(code) := r.activity if {
	some r in programme.takeover_activities
	code in split(r.measure, "/")
}

public_exception(code, y) if {
	some r in programme.public_entity_exceptions
	r.measure == code
	y >= r.from_year
	y <= r.through_year
}

annually_variable(unit) if unit in programme.annually_variable_units

management_exception(code, area, y) if {
	some r in programme.minimum_management_exemptions
	code in split(r.measure, "/")
	area == r.area
	y >= 2023
	y <= r.through_year
	contract_available(code, y)
}

contract_available(code, y) if {
	code != "1C"
	y >= 2023
}

contract_available("1C", y) if y >= 2025

permitted_access_ha(code, base_2025, y) := max([5, base_2025 * 0.5]) if {
	code in programme.area_gain_limit
	y >= 2026
	y <= 2028
	base_2025 >= 0
}

farm_conflict(first, second, bio_part) if {
	some r in programme.farm_conflicts
	{first, second} == {r.first, r.second}
	not applicable_bio_exception(r, bio_part)
}

applicable_bio_exception(r, part) if {
	part == true
	r.bio_part_farm_exception
}

harvest_exempt_parcels contains p.parcel_id if {
	some p in input.land.parcels
	drought_harvest_waiver(p.harvest_exception_2026, year)
}

assessed_sanction_pct := sanction_percent(year, g.sanction_level)

package oepul.o6_21_test

import data.oepul.o6_21 as rule
import rego.v1

steer(tag) := {
	"tag": tag, "birth_date": "2021-01-10", "breed": "Fleckvieh", "sex": "male",
	"periods": [{"first_day": "2024-01-01", "last_day": "2024-12-31", "country": "AT"}],
	"withdrawn_for_year": false, "animal_conditions_met": true, "overlap_claims": [],
}

farm(cattle) := {"farm": {"year": 2024, "oepul": {"home_area_ha": 220}}, "o6_21": {
